local controller_base = get_or_create_global_variable('Quest/Base/QuestControllerBase')

---@class ShortStoryNoelWaveringFaithController : QuestControllerBase
local local_class = newclass('ShortStoryNoelWaveringFaithController', controller_base)

function local_class:init(cs_controller)
	self.super:init(cs_controller)

	-- 사용할 섹션 스크립트 정보. 주석 해제하고 사용
	self.script_config = {
		HasPreSection = false,
		NormalSectionCount = 1,
		HasPostSection = true
	}

	self.scene_version = scene_util.default_version + 1

	--fx
	self.fx = metatable_helper.create_fx_accessor({
		reset = function()
			return unity_object_pool.GetOrCreate('FX_reset_object')
		end,
	})
end

function local_class:load_resource()
	self.fx:load_async()
end

function local_class:dispose()
	self.super:dispose()
end

function local_class:on_event(e)
	return false
end

function local_class:on_stage_loaded()
end

function local_class:on_stage_end()
end

function local_class:reset_brazier()
	local brazier = get_field_object('wavering_faith_brazier')

	local effect_size = brazier.Bounds.size

	local prev_pos_effect = self.fx.reset():Instantiate(brazier.Bounds.center)
	prev_pos_effect.transform.localScale = effect_size

	brazier.Position = field_util.get_marker_pos('wavering_faith_gnome_pos_1') + vector(1, 0, 0)

	local current_pos_effect = self.fx.reset():Instantiate(brazier.Bounds.center)
	current_pos_effect.transform.localScale = effect_size
end

return local_class

