		local watcher = self.npc.watch_mafia(i)

		watcher.FieldObjectController = CS.Oak.NPCCharacterController()
	end
end

function local_class:set_oneline_npc()
	local place_oneline_npc = function(oneline_npc, place_info)
		if place_info.pos ~= nil then
			character_util.set_position(oneline_npc, place_info.pos)
		end

		if place_info.dir ~= nil then
			scene_util.set_direction(oneline_npc, place_info.dir, false)
		end

		if place_info.emo ~= nil then
			scene_util.set_emotion(oneline_npc, self, place_info.emo)
		else
			character_util.remove_emotion(oneline_npc)
		end

		if place_info.anim ~= nil then
			scene_util.set_anim(oneline_npc, self, place_info.anim)
		else
			character_util.remove_anim(oneline_npc)
		end

		if place_info.emoticon_interactable ~= nil then
			oneline_npc.Interactable = CS.Oak.EmoticonInteractable.Create(place_info.emoticon_interactable)
		end

		if place_info.emoticon_interacting_sfx ~= nil then
			oneline_npc.Interactable.InteractingSfx = place_info.emoticon_interacting_sfx
		end

		if place_info.string_key ~= nil then
			oneline_npc.Interactable.Talk = place_info.string_key
			oneline_npc.Interactable.TalkSfx = place_info.string_sfx
		end
	end

	if self.cs_section.IsStartedOnThis then
		self.controller:set_current_scene_npc(self.controller.npc_placement_group.underground)

		local closed_mousetrap = self.field_object.closed_mousetrap()
		local opened_mousetrap = self.field_object.opened_mousetrap()
		local backup_pos = closed_mousetrap.Position

		closed_mousetrap.Position = vector(999, 0, 999)
		opened_mousetrap.Position = backup_pos

		local cracked_floor = self.field_object.cracked_floor(1)
		local crack_floor = cracked_floor.transform:Find('crack')
		local break_floor = cracked_floor.transform:Find('break')

		crack_floor.gameObject:SetActive(false)
		break_floor.gameObject:SetActive(true)

		local hole = self.field_object.post_hole()
		local renderer = hole:GetComponent(typeof(CS.UnityEngine.MeshRenderer))
		hole.Position = vector(47, 0, 70)
		renderer.enabled = false
	end

	local npc = self.npc.underground_mafia(3)
	scene_util.set_anim(npc, self, 'seat')
	character_util.spine_remove_attachment(npc, '[base]weapon1')

	--덩치 쥐1 (down, idle, idle) : 앞으로 쥐덫은 제가 다 부숴놓겠습니다.
	place_oneline_npc(self.npc.mafia_guard(1),
			{
				pos = self.marker.boss_room_guard_mafia(1, 4),
				dir = 'down',
				string_key = 'ss_noel_zootopia_post_oneline_1_1',
				string_sfx = nil,
			} )

	--덩치 쥐2 (down, idle, idle) : 보스, 명령만 주시죠.
	place_oneline_npc(self.npc.mafia_guard(2),
			{
				pos = self.marker.boss_room_guard_mafia(2, 4),
				dir = 'down',
				string_key = 'ss_noel_zootopia_post_oneline_1_2',
				string_sfx = nil,
			} )

	--아가씨 쥐 (right, smile, idle) : 고마워요. 덕분에 이제 안 아파요.
	place_oneline_npc(self.npc.daughter(),
			{
				pos = self.marker.daughter(2, 2),
				dir = 'right',
				emo = 'smile',
				string_key = 'ss_noel_zootopia_post_oneline_1_3',
				string_sfx = '03_dialogue_positive_01',
			} )

	--대부 쥐 (down, idle, idle) : 앞으로는 쥐덫 관리를 신경써서 해야겠군.
	place_oneline_npc(self.npc.boss(),
			{
				pos = self.marker.boss(2, 3),
				dir = 'down',
				string_key = 'ss_noel_zootopia_post_oneline_1_4',
			} )

	--마피아 쥐7 (right, tired, bomb_idle): 그나저나… 치즈 창고가 텅 빈건 그 뚱뚱한 녀석이 쫓겨난 뒤로는 처음이구만.
	place_oneline_npc(self.npc.mafia(1),
			{
				pos = field_util.get_marker_pos('sub_zootopia_boss_room_mafia_oneline_1'),
				dir = 'right',
				emo = 'tired',
				anim = 'bomb_idle',
				string_key = 'ss_noel_zootopia_post_oneline_1_5',
			} )

	--생쥐 (down, cast, doyagao): 생쥐는 사실… 잘못 있어…!
	place_oneline_npc(self.npc.mouse(1),
			{
				pos = field_util.get_marker_pos('sub_zootopia_boss_room_mouse_oneline_1'),
				dir = 'down',
				emo = 'doyagao',
				anim = 'cast',
				string_key = 'ss_noel_zootopia_post_oneline_1_6',
				string_sfx = '01_bad_fairy_01',
			} )

	--마피아 쥐 감시범위 작동하지 않는다.
	--좌, 우를 번갈아서 감시하던 마피아 쥐의 경우, 최초 방향으로 고정된다.
	--인터렉트할 경우 이모티콘 출력, 마피아 쥐 (현재 방향, smile, idle) happy 이모티콘 출력, async

	--감시 쥐 1번
	place_oneline_npc(self.npc.watch_mafia(1),
			{
				emo = 'smile',
				emoticon_interactable = emoticon_type.happy,
				emoticon_interacting_sfx = '03_dialogue_positive_02',
			} )

	--감시 쥐 2번
	place_oneline_npc(self.npc.watch_mafia(2),
			{
				emo = 'smile',
				emoticon_interactable = emoticon_type.happy,
				emoticon_interacting_sfx = '03_dialogue_positive_02',
			} )

	--감시 쥐 3번
	place_oneline_npc(self.npc.watch_mafia(3),
			{
				dir = 'up',
				emo = 'smile',
				emoticon_interactable = emoticon_type.happy,
				emoticon_interacting_sfx = '03_dialogue_positive_02',
			} )

	--감시 쥐 4번
	place_oneline_npc(self.npc.watch_mafia(4),
			{
				emo = 'smile',
				emoticon_interactable = emoticon_type.happy,
				emoticon_interacting_sfx = '03_dialogue_positive_02',
			} )

	--감시 쥐 5번
	place_oneline_npc(self.npc.watch_mafia(5),
			{
				pos = field_util.get_marker_pos('sub_zootopia_watcher_5') + vector(0, 0, 1),
				dir = 'down',
				emo = 'smile',
				emoticon_interactable = emoticon_type.happy,
				emoticon_interacting_sfx = '03_dialogue_positive_02',
			} )
end

return local_class

